create or replace function public.get_or_create_current_profile() returns public.profiles language plpgsql security definer set search_path=public,auth,extensions as $$ declare v_profile public.profiles; begin if auth.uid() is null then raise exception 'authentication_required'; end if; select * into v_profile from public.profiles where user_id=auth.uid() limit 1; if v_profile.id is null then insert into public.profiles(user_id,created_at,updated_at) values(auth.uid(),now(),now()) returning * into v_profile; end if; return v_profile; end; $$;